import React, { useState, useEffect } from "react";

// Base URL of the backend API (see /backend in this project). Point this at
// your deployed API once it's live — for local dev with `npm run dev` in
// the backend folder, http://localhost:4000 is the default.
const API_BASE_URL = "http://localhost:4000";

async function apiFetch(path, options = {}) {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.error || `Request failed (${res.status})`);
  }
  return data;
}

// Same as apiFetch, but attaches the admin password header. adminPassword
// is kept in React state only (never localStorage) — the person re-enters
// it each time they reload the page.
async function adminFetch(path, adminPassword, options = {}) {
  return apiFetch(path, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      "x-admin-password": adminPassword,
      ...(options.headers || {}),
    },
  });
}

