// Coastal-botanical line motif — a single wave under a single stem,
// standing in for "Umdloti" (the coast) and "Sativa" (the plant)
// without reaching for a literal leaf icon.
function Motif({ className = "", stroke = COLORS.green, opacity = 1 }) {
  return (
    <svg
      viewBox="0 0 240 120"
      className={className}
      style={{ opacity }}
      fill="none"
    >
      <path
        d="M8 92c22-14 40-14 60 0s38 14 60 0 38-14 60 0 38 14 44 6"
        stroke={stroke}
        strokeWidth="1.4"
        strokeLinecap="round"
      />
      <path
        d="M120 92V26"
        stroke={stroke}
        strokeWidth="1.4"
        strokeLinecap="round"
      />
      <path
        d="M120 40c10-4 18-2 22 8-10 4-18 2-22-8Z"
        stroke={stroke}
        strokeWidth="1.4"
        strokeLinejoin="round"
      />
      <path
        d="M120 54c-10-4-18-2-22 8 10 4 18 2 22-8Z"
        stroke={stroke}
        strokeWidth="1.4"
        strokeLinejoin="round"
      />
      <path
        d="M120 68c10-4 18-2 22 8-10 4-18 2-22-8Z"
        stroke={stroke}
        strokeWidth="1.4"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function AgeGate({ onVerified }) {
  const [dob, setDob] = useState("");
  const [error, setError] = useState("");

  const check = (e) => {
    e.preventDefault();
    if (!dob) {
      setError("Enter your date of birth to continue");
      return;
    }
    const age =
      (Date.now() - new Date(dob).getTime()) / (1000 * 60 * 60 * 24 * 365.25);
    if (age < 18) {
      setError("You must be 18 or older to enter this site");
      return;
    }
    onVerified();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center px-6"
      style={{ background: COLORS.greenDeep }}
    >
      <div className="max-w-sm w-full text-center">
        <img
          src={LOGO_SRC}
          alt="Sativa Umdloti"
          className="w-20 h-20 mx-auto mb-8"
        />
        <div
          className="text-[11px] tracking-[0.18em] uppercase mb-3"
          style={{ color: COLORS.amber }}
        >
          18+ only
        </div>
        <h1
          className="font-serif text-[28px] leading-tight mb-3"
          style={{ color: COLORS.paper }}
        >
          Sativa Umdloti
        </h1>
        <p
          className="text-[14px] leading-relaxed mb-8"
          style={{ color: "#C9CFC2" }}
        >
          You need to be 18 or older to enter. Confirm your date of birth
          to continue.
        </p>
        <form onSubmit={check} className="text-left">
          <label className="block mb-1">
            <span
              className="text-[11px] tracking-[0.14em] uppercase"
              style={{ color: COLORS.amber }}
            >
              Date of birth
            </span>
          </label>
          <input
            type="date"
            value={dob}
            onChange={(e) => {
              setDob(e.target.value);
              setError("");
            }}
            className="w-full bg-transparent border-b px-0 py-2.5 text-[15px] focus:outline-none"
            style={{
              borderColor: error ? "#E08A6E" : "rgba(247,245,239,0.35)",
              color: COLORS.paper,
              colorScheme: "dark",
            }}
          />
          {error && (
            <p className="text-[12px] mt-2" style={{ color: "#E08A6E" }}>
              {error}
            </p>
          )}
          <button
            type="submit"
            className="w-full mt-8 py-3.5 text-[13px] tracking-[0.12em] uppercase font-medium"
            style={{ background: COLORS.amber, color: COLORS.greenDeep }}
          >
            Enter site
          </button>
        </form>
        <p
          className="text-[11px] mt-6 leading-relaxed"
          style={{ color: "#8FA087" }}
        >
          By entering, you confirm you are 18 years of age or older.
        </p>
      </div>
    </div>
  );
}

