function CheckoutPage({ products, cart, onBack, onPlaceOrder }) {
  const [details, setDetails] = useState({
    fullName: "",
    email: "",
    phone: "",
    address: "",
  });
  const [payment, setPayment] = useState("card");
  const [errors, setErrors] = useState({});
  const [placing, setPlacing] = useState(false);
  const [orderError, setOrderError] = useState("");

  const lines = Object.entries(cart)
    .filter(([, qty]) => qty > 0)
    .map(([id, qty]) => ({ product: products.find((p) => p.id === id), qty }));
  const subtotal = lines.reduce(
    (sum, line) => sum + line.product.price * line.qty,
    0
  );

  const set = (key) => (e) => {
    setDetails((d) => ({ ...d, [key]: e.target.value }));
    if (errors[key]) setErrors((er) => ({ ...er, [key]: null }));
  };

  const validate = () => {
    const req = {
      fullName: "Enter your full name",
      email: "Enter a contact email",
      phone: "Enter a contact number",
      address: "Enter a delivery address",
    };
    const next = {};
    Object.entries(req).forEach(([k, msg]) => {
      if (!String(details[k]).trim()) next[k] = msg;
    });
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handlePlaceOrder = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setPlacing(true);
    setOrderError("");
    try {
      const items = lines.map(({ product, qty }) => ({
        productId: product.id,
        qty,
      }));
      const result = await apiFetch("/api/orders", {
        method: "POST",
        body: JSON.stringify({
          fullName: details.fullName,
          email: details.email,
          phone: details.phone,
          address: details.address,
          paymentMethod: payment,
          items,
        }),
      });
      // result.payment.redirectUrl points at the gateway's hosted payment
      // page once Peach/Stitch are actually wired up server-side. Until
      // then the backend returns a placeholder and we go straight to the
      // confirmation screen.
      onPlaceOrder(result.orderId);
    } catch (err) {
      setOrderError(err.message || "Could not place your order. Please try again.");
    } finally {
      setPlacing(false);
    }
  };

  return (
    <div className="min-h-screen" style={{ background: COLORS.paper }}>
      <div className="max-w-2xl mx-auto px-6 sm:px-10 py-14 sm:py-20">
        <button
          onClick={onBack}
          className="text-[12px] tracking-[0.1em] uppercase mb-8 underline underline-offset-4"
          style={{ color: COLORS.green }}
        >
          ← Back to cart
        </button>
        <h1
          className="font-serif text-[32px] sm:text-[40px] leading-tight mb-10"
          style={{ color: COLORS.ink }}
        >
          Checkout
        </h1>

        <form onSubmit={handlePlaceOrder} noValidate>
          <div
            className="p-7 sm:p-9 mb-8"
            style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}` }}
          >
            <h2
              className="text-[11px] tracking-[0.14em] uppercase mb-6 pb-3 border-b"
              style={{ color: COLORS.greenDeep, borderColor: COLORS.line }}
            >
              Delivery details
            </h2>

            <Field label="Full name" required error={errors.fullName}>
              <TextInput value={details.fullName} onChange={set("fullName")} error={errors.fullName} />
            </Field>
            <div className="grid grid-cols-2 gap-6">
              <Field label="Email" required error={errors.email}>
                <TextInput type="email" value={details.email} onChange={set("email")} error={errors.email} />
              </Field>
              <Field label="Phone" required error={errors.phone}>
                <TextInput type="tel" value={details.phone} onChange={set("phone")} error={errors.phone} />
              </Field>
            </div>
            <Field label="Delivery address" required error={errors.address}>
              <TextInput value={details.address} onChange={set("address")} error={errors.address} />
            </Field>
          </div>

          <div
            className="p-7 sm:p-9 mb-8"
            style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}` }}
          >
            <h2
              className="text-[11px] tracking-[0.14em] uppercase mb-6 pb-3 border-b"
              style={{ color: COLORS.greenDeep, borderColor: COLORS.line }}
            >
              Payment
            </h2>
            <div className="flex flex-col gap-3 mb-2">
              {[
                { id: "card", label: "Card (Peach Payments)" },
                { id: "eft", label: "Instant EFT (Stitch)" },
              ].map((opt) => (
                <label
                  key={opt.id}
                  className="flex items-center gap-3 cursor-pointer text-[14px]"
                  style={{ color: COLORS.ink }}
                >
                  <input
                    type="radio"
                    name="payment"
                    checked={payment === opt.id}
                    onChange={() => setPayment(opt.id)}
                    style={{ accentColor: COLORS.green }}
                  />
                  {opt.label}
                </label>
              ))}
            </div>
            <p className="text-[12px] mt-3" style={{ color: "#8A8371" }}>
              You'll enter your payment details on the next, secure step.
            </p>
          </div>

          <div className="flex items-center justify-between mb-8">
            <span
              className="text-[13px] tracking-[0.1em] uppercase"
              style={{ color: COLORS.greenDeep }}
            >
              Total
            </span>
            <span className="font-serif text-[24px]" style={{ color: COLORS.ink }}>
              {formatZAR(subtotal)}
            </span>
          </div>

          {orderError && (
            <p
              className="text-[13px] mb-4"
              style={{ color: COLORS.error }}
            >
              {orderError}
            </p>
          )}

          <button
            type="submit"
            disabled={placing || lines.length === 0}
            className="w-full sm:w-auto px-8 py-3.5 text-[13px] tracking-[0.12em] uppercase font-medium disabled:opacity-60"
            style={{ background: COLORS.green, color: COLORS.paper }}
          >
            {placing ? "Placing order…" : "Place order"}
          </button>
        </form>
      </div>
    </div>
  );
}

