const FIELD_BASE =
  "w-full bg-transparent border-0 border-b px-0 py-2.5 text-[15px] " +
  "focus:outline-none focus:ring-0 transition-colors placeholder:text-[#9C9484]";


function Field({ label, required, error, children, hint }) {
  return (
    <label className="block mb-7">
      <span className="flex items-baseline justify-between mb-1">
        <span
          className="text-[11px] tracking-[0.14em] uppercase font-medium"
          style={{ color: COLORS.green }}
        >
          {label}
          {required && <span style={{ color: COLORS.amber }}> *</span>}
        </span>
        {hint && (
          <span className="text-[11px]" style={{ color: "#8A8371" }}>
            {hint}
          </span>
        )}
      </span>
      {children}
      {error && (
        <span
          className="block text-[12px] mt-1.5"
          style={{ color: COLORS.error }}
        >
          {error}
        </span>
      )}
    </label>
  );
}

function TextInput(props) {
  const { error, ...rest } = props;
  return (
    <input
      {...rest}
      className={FIELD_BASE}
      style={{
        borderColor: error ? COLORS.error : COLORS.line,
        color: COLORS.ink,
      }}
      onFocus={(e) => (e.target.style.borderColor = COLORS.green)}
      onBlur={(e) =>
        (e.target.style.borderColor = error ? COLORS.error : COLORS.line)
      }
    />
  );
}

function FileInput({ id, value, onChange, error }) {
  return (
    <div>
      <input
        id={id}
        type="file"
        accept=".pdf,.jpg,.jpeg,.png"
        className="hidden"
        onChange={(e) => onChange(e.target.files?.[0] || null)}
      />
      <label
        htmlFor={id}
        className="flex items-center justify-between cursor-pointer border-b py-2.5 group"
        style={{ borderColor: error ? COLORS.error : COLORS.line }}
      >
        <span
          className="text-[15px] truncate pr-3"
          style={{ color: value ? COLORS.ink : "#9C9484" }}
        >
          {value ? value.name : "No file selected"}
        </span>
        <span
          className="text-[11px] tracking-[0.1em] uppercase shrink-0 px-3 py-1.5 rounded-full border transition-colors"
          style={{ borderColor: COLORS.green, color: COLORS.green }}
        >
          Choose file
        </span>
      </label>
    </div>
  );
}

const initialForm = {
  fullName: "",
  idNumber: "",
  dob: "",
  email: "",
  phone: "",
  address: "",
  consent: false,
};


function RegistrationForm({ onBack }) {
  const [form, setForm] = useState(initialForm);
  const [errors, setErrors] = useState({});
  const [status, setStatus] = useState("form"); // form | submitting | submitted

  const set = (key) => (e) => {
    const value =
      e && e.target
        ? e.target.type === "checkbox"
          ? e.target.checked
          : e.target.value
        : e;
    setForm((f) => ({ ...f, [key]: value }));
    if (errors[key]) setErrors((er) => ({ ...er, [key]: null }));
  };

  const validate = () => {
    const req = {
      fullName: "Enter your full name",
      idNumber: "Enter a South African ID or passport number",
      dob: "Enter a date of birth",
      email: "Enter a contact email",
      phone: "Enter a contact number",
      address: "Enter a residential address",
    };
    const next = {};
    Object.entries(req).forEach(([k, msg]) => {
      if (!String(form[k]).trim()) next[k] = msg;
    });
    if (!form.consent) next.consent = "Consent is required to proceed";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const [submitError, setSubmitError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;
    setStatus("submitting");
    setSubmitError("");
    try {
      await apiFetch("/api/customers/register", {
        method: "POST",
        body: JSON.stringify({
          fullName: form.fullName,
          idNumber: form.idNumber,
          dob: form.dob,
          email: form.email,
          phone: form.phone,
          address: form.address,
          consent: form.consent,
        }),
      });
      setStatus("submitted");
    } catch (err) {
      setSubmitError(err.message || "Could not complete registration. Please try again.");
      setStatus("form");
    }
  };

  if (status === "submitted") {
    return (
      <div
        className="min-h-screen flex items-center justify-center px-6"
        style={{ background: COLORS.paper }}
      >
        <div className="max-w-md text-center">
          <div
            className="w-12 h-12 rounded-full mx-auto mb-6 flex items-center justify-center"
            style={{ background: COLORS.green }}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
              <path
                d="M4 12.5 9.5 18 20 6"
                stroke="#F7F5EF"
                strokeWidth="2.4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </div>
          <h1
            className="font-serif text-[26px] mb-3"
            style={{ color: COLORS.ink }}
          >
            Registration received
          </h1>
          <p className="text-[15px] leading-relaxed" style={{ color: "#5B5645" }}>
            Thanks for registering. You're all set — you can start browsing
            and ordering right away. We'll send confirmations and order
            updates to{" "}
            <strong style={{ color: COLORS.ink }}>{form.email}</strong>.
          </p>
          <button
            onClick={onBack}
            className="mt-8 text-[13px] tracking-[0.1em] uppercase underline underline-offset-4"
            style={{ color: COLORS.green }}
          >
            Back to site
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen" style={{ background: COLORS.paper }}>
      <div className="max-w-xl mx-auto px-6 py-14 sm:py-20">
        <button
          onClick={onBack}
          className="text-[12px] tracking-[0.1em] uppercase mb-8 underline underline-offset-4"
          style={{ color: COLORS.green }}
        >
          ← Back to site
        </button>
        <img src={LOGO_SRC} alt="Sativa Umdloti" className="w-14 h-14 mb-6" />
        <div
          className="text-[11px] tracking-[0.18em] uppercase mb-3"
          style={{ color: COLORS.amber }}
        >
          Sativa Umdloti · 18+ only
        </div>
        <h1
          className="font-serif text-[32px] sm:text-[38px] leading-[1.1] mb-4"
          style={{ color: COLORS.ink }}
        >
          Create your account
        </h1>
        <p
          className="text-[15px] leading-relaxed mb-12 max-w-md"
          style={{ color: "#5B5645" }}
        >
          You need to be 18 or older to buy from Sativa Umdloti. Fill in
          your details below to create an account — once you're
          registered, you're free to order.
        </p>

        <form onSubmit={handleSubmit} noValidate>
          <div
            className="p-7 sm:p-9 rounded-sm mb-8"
            style={{ background: COLORS.panel, border: `1px solid ${COLORS.line}` }}
          >
            <h2
              className="text-[11px] tracking-[0.14em] uppercase mb-6 pb-3 border-b"
              style={{ color: COLORS.greenDeep, borderColor: COLORS.line }}
            >
              Your details
            </h2>

            <Field label="Full name" required error={errors.fullName}>
              <TextInput
                value={form.fullName}
                onChange={set("fullName")}
                error={errors.fullName}
                placeholder="As it appears on your ID"
              />
            </Field>

            <div className="grid grid-cols-2 gap-6">
              <Field label="ID / passport number" required error={errors.idNumber}>
                <TextInput
                  value={form.idNumber}
                  onChange={set("idNumber")}
                  error={errors.idNumber}
                />
              </Field>
              <Field label="Date of birth" required error={errors.dob}>
                <TextInput
                  type="date"
                  value={form.dob}
                  onChange={set("dob")}
                  error={errors.dob}
                />
              </Field>
            </div>

            <div className="grid grid-cols-2 gap-6">
              <Field label="Email" required error={errors.email}>
                <TextInput
                  type="email"
                  value={form.email}
                  onChange={set("email")}
                  error={errors.email}
                  placeholder="you@example.com"
                />
              </Field>
              <Field label="Phone" required error={errors.phone}>
                <TextInput
                  type="tel"
                  value={form.phone}
                  onChange={set("phone")}
                  error={errors.phone}
                  placeholder="0XX XXX XXXX"
                />
              </Field>
            </div>

            <Field label="Residential address" required error={errors.address}>
              <TextInput
                value={form.address}
                onChange={set("address")}
                error={errors.address}
              />
            </Field>
          </div>

          <label className="flex items-start gap-3 mb-2 cursor-pointer">
            <input
              type="checkbox"
              checked={form.consent}
              onChange={set("consent")}
              className="mt-1"
              style={{ accentColor: COLORS.green }}
            />
            <span className="text-[13px] leading-relaxed" style={{ color: "#5B5645" }}>
              I confirm I am 18 years or older, the information provided is
              accurate, and I consent to Sativa Umdloti processing my
              personal information in accordance with POPIA for the purpose
              of this registration.
            </span>
          </label>
          {errors.consent && (
            <span className="block text-[12px] mb-6" style={{ color: COLORS.error }}>
              {errors.consent}
            </span>
          )}

          {submitError && (
            <p className="text-[13px] mb-2" style={{ color: COLORS.error }}>
              {submitError}
            </p>
          )}

          <button
            type="submit"
            disabled={status === "submitting"}
            className="w-full sm:w-auto mt-6 px-8 py-3.5 text-[13px] tracking-[0.12em] uppercase font-medium transition-opacity disabled:opacity-60"
            style={{ background: COLORS.green, color: COLORS.paper }}
          >
            {status === "submitting" ? "Submitting…" : "Submit registration"}
          </button>
        </form>
      </div>
    </div>
  );
}

// --- Store admin: order & customer management, password-gated ---

function AdminLogin({ onLoggedIn, onBack }) {
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [checking, setChecking] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!password) return;
    setChecking(true);
    setError("");
    try {
      await apiFetch("/api/admin/login", {
        method: "POST",
        body: JSON.stringify({ password }),
      });
      onLoggedIn(password);
    } catch (err) {
      setError(err.message || "Could not log in");
    } finally {
      setChecking(false);
    }
  };

  return (
    <div
      className="min-h-screen flex items-center justify-center px-6"
      style={{ background: COLORS.paper }}
    >
      <div className="max-w-sm w-full">
        <button
          onClick={onBack}
          className="text-[12px] tracking-[0.1em] uppercase mb-8 underline underline-offset-4"
          style={{ color: COLORS.green }}
        >
          ← Back to site
        </button>
        <div
          className="text-[11px] tracking-[0.18em] uppercase mb-3"
          style={{ color: COLORS.amber }}
        >
          Store admin
        </div>
        <h1
          className="font-serif text-[28px] leading-tight mb-8"
          style={{ color: COLORS.ink }}
        >
          Sign in
        </h1>
        <form onSubmit={handleSubmit}>
          <label className="block mb-6">
            <span
              className="text-[11px] tracking-[0.14em] uppercase mb-1 block"
              style={{ color: COLORS.green }}
            >
              Password
            </span>
            <input
              type="password"
              autoFocus
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setError("");
              }}
              className="w-full bg-transparent border-0 border-b px-0 py-2.5 text-[15px] focus:outline-none"
              style={{
                borderColor: error ? COLORS.error : COLORS.line,
                color: COLORS.ink,
              }}
            />
          </label>
          {error && (
            <p className="text-[13px] mb-4" style={{ color: COLORS.error }}>
              {error}
            </p>
          )}
          <button
            type="submit"
            disabled={checking}
            className="w-full px-8 py-3.5 text-[13px] tracking-[0.12em] uppercase font-medium disabled:opacity-60"
            style={{ background: COLORS.green, color: COLORS.paper }}
          >
            {checking ? "Checking…" : "Sign in"}
          </button>
        </form>
      </div>
    </div>
  );
}

const ORDER_STATUSES = [
  "received",
  "preparing",
  "out_for_delivery",
  "delivered",
  "cancelled",
];

function statusLabel(status) {
  return status.replace(/_/g, " ");
}

function AdminDashboard({ adminPassword, onLogout, onBack }) {
  const [tab, setTab] = useState("orders"); // orders | customers
  const [orders, setOrders] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const loadOrders = () =>
    adminFetch("/api/admin/orders", adminPassword).then(setOrders);
  const loadCustomers = () =>
    adminFetch("/api/admin/customers", adminPassword).then(setCustomers);

  useEffect(() => {
    setLoading(true);
    setError("");
    Promise.all([loadOrders(), loadCustomers()])
      .catch((err) => setError(err.message || "Could not load admin data"))
      .finally(() => setLoading(false));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const updateStatus = async (orderId, status) => {
    // Optimistic update so the dropdown feels instant.
    setOrders((prev) =>
      prev.map((o) => (o.id === orderId ? { ...o, status } : o))
    );
    try {
      await adminFetch(`/api/admin/orders/${orderId}`, adminPassword, {
        method: "PATCH",
        body: JSON.stringify({ status }),
      });
    } catch (err) {
      setError(err.message || "Could not update order");
      loadOrders(); // revert to server truth on failure
    }
  };

  return (
    <div className="min-h-screen" style={{ background: COLORS.paper }}>
      <div className="max-w-5xl mx-auto px-6 sm:px-10 py-14 sm:py-20">
        <div className="flex items-center justify-between mb-8">
          <button
            onClick={onBack}
            className="text-[12px] tracking-[0.1em] uppercase underline underline-offset-4"
            style={{ color: COLORS.green }}
          >
            ← Back to site
          </button>
          <button
            onClick={onLogout}
            className="text-[12px] tracking-[0.1em] uppercase underline underline-offset-4"
            style={{ color: "#8A8371" }}
          >
            Log out
          </button>
        </div>

        <h1
          className="font-serif text-[32px] sm:text-[40px] leading-tight mb-8"
          style={{ color: COLORS.ink }}
        >
          Store admin
        </h1>

        <div className="flex gap-6 mb-10 border-b" style={{ borderColor: COLORS.line }}>
          {["orders", "customers"].map((t) => (
            <button
              key={t}
              onClick={() => setTab(t)}
              className="pb-3 text-[12px] tracking-[0.1em] uppercase"
              style={{
                color: tab === t ? COLORS.greenDeep : "#8A8371",
                borderBottom: tab === t ? `2px solid ${COLORS.green}` : "2px solid transparent",
              }}
            >
              {t === "orders" ? `Orders (${orders.length})` : `Customers (${customers.length})`}
            </button>
          ))}
        </div>

        {error && (
          <p className="text-[13px] mb-6" style={{ color: COLORS.error }}>
            {error}
          </p>
        )}

        {loading ? (
          <p className="text-[14px]" style={{ color: "#8A8371" }}>
            Loading…
          </p>
        ) : tab === "orders" ? (
          orders.length === 0 ? (
            <p className="text-[14px]" style={{ color: "#8A8371" }}>
              No orders yet.
            </p>
          ) : (
            <div className="flex flex-col gap-4">
              {orders.map((order) => (
                <div
                  key={order.id}
                  className="p-6 border"
                  style={{ borderColor: COLORS.line, background: COLORS.panel }}
                >
                  <div className="flex flex-wrap items-start justify-between gap-4 mb-4">
                    <div>
                      <div className="font-serif text-[18px]" style={{ color: COLORS.ink }}>
                        {order.fullName}
                      </div>
                      <div className="text-[13px]" style={{ color: "#5B5645" }}>
                        {order.email} · {order.phone}
                      </div>
                      <div className="text-[13px]" style={{ color: "#5B5645" }}>
                        {order.address}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="font-serif text-[20px]" style={{ color: COLORS.ink }}>
                        {formatZAR(order.subtotal)}
                      </div>
                      <div
                        className="text-[11px] uppercase tracking-[0.08em]"
                        style={{ color: "#8A8371" }}
                      >
                        {order.paymentMethod} · {order.paymentStatus}
                      </div>
                    </div>
                  </div>

                  <ul className="text-[13px] mb-4" style={{ color: "#5B5645" }}>
                    {order.items.map((item, i) => (
                      <li key={i}>
                        {item.qty} × {item.name} — {formatZAR(item.price * item.qty)}
                      </li>
                    ))}
                  </ul>

                  <div className="flex items-center justify-between">
                    <span className="text-[12px]" style={{ color: "#8A8371" }}>
                      {new Date(order.createdAt).toLocaleString()}
                    </span>
                    <select
                      value={order.status}
                      onChange={(e) => updateStatus(order.id, e.target.value)}
                      className="text-[12px] tracking-[0.06em] uppercase px-3 py-2 border"
                      style={{ borderColor: COLORS.line, color: COLORS.ink, background: COLORS.paper }}
                    >
                      {ORDER_STATUSES.map((s) => (
                        <option key={s} value={s}>
                          {statusLabel(s)}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              ))}
            </div>
          )
        ) : customers.length === 0 ? (
          <p className="text-[14px]" style={{ color: "#8A8371" }}>
            No registrations yet.
          </p>
        ) : (
          <div className="flex flex-col gap-4">
            {customers.map((c) => (
              <div
                key={c.id}
                className="p-6 border"
                style={{ borderColor: COLORS.line, background: COLORS.panel }}
              >
                <div className="font-serif text-[18px] mb-1" style={{ color: COLORS.ink }}>
                  {c.full_name}
                </div>
                <div className="text-[13px]" style={{ color: "#5B5645" }}>
                  {c.email} · {c.phone}
                </div>
                <div className="text-[13px]" style={{ color: "#5B5645" }}>
                  {c.address}
                </div>
                <div className="text-[12px] mt-2" style={{ color: "#8A8371" }}>
                  Registered {new Date(c.created_at).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default function App() {
  const [verified, setVerified] = useState(false);
  const [view, setView] = useState("home"); // home | register | catalogue | cart | checkout | order-confirmed
  const [cart, setCart] = useState({}); // { [productId]: qty }
  const [products, setProducts] = useState(FALLBACK_PRODUCTS);
  const [lastOrderId, setLastOrderId] = useState(null);
  const [adminPassword, setAdminPassword] = useState(null);

  useEffect(() => {
    let cancelled = false;
    apiFetch("/api/products")
      .then((data) => {
        if (!cancelled && Array.isArray(data) && data.length > 0) {
          setProducts(data);
        }
      })
      .catch(() => {
        // Backend unreachable — keep showing FALLBACK_PRODUCTS so the
        // storefront isn't blank while you're developing without the API
        // running.
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const addToCart = (id) =>
    setCart((c) => ({ ...c, [id]: (c[id] || 0) + 1 }));
  const setQty = (id, qty) =>
    setCart((c) => ({ ...c, [id]: Math.max(0, qty) }));
  const removeFromCart = (id) =>
    setCart((c) => {
      const next = { ...c };
      delete next[id];
      return next;
    });
  const cartCount = Object.values(cart).reduce((sum, q) => sum + q, 0);

  return (
    <div style={{ background: COLORS.paper }}>
      {!verified && <AgeGate onVerified={() => setVerified(true)} />}

      {view === "register" && (
        <RegistrationForm onBack={() => setView("home")} />
      )}

      {view === "catalogue" && (
        <CataloguePage
          products={products}
          cart={cart}
          onAdd={addToCart}
          onCart={() => setView("cart")}
          onBack={() => setView("home")}
        />
      )}

      {view === "cart" && (
        <CartPage
          products={products}
          cart={cart}
          onSetQty={setQty}
          onRemove={removeFromCart}
          onBack={() => setView("catalogue")}
          onCheckout={() => setView("checkout")}
        />
      )}

      {view === "checkout" && (
        <CheckoutPage
          products={products}
          cart={cart}
          onBack={() => setView("cart")}
          onPlaceOrder={(orderId) => {
            setLastOrderId(orderId);
            setCart({});
            setView("order-confirmed");
          }}
        />
      )}

      {view === "order-confirmed" && (
        <OrderConfirmedPage orderId={lastOrderId} onBack={() => setView("home")} />
      )}

      {view === "admin-login" && (
        <AdminLogin
          onLoggedIn={(password) => {
            setAdminPassword(password);
            setView("admin");
          }}
          onBack={() => setView("home")}
        />
      )}

      {view === "admin" && (
        <AdminDashboard
          adminPassword={adminPassword}
          onLogout={() => {
            setAdminPassword(null);
            setView("home");
          }}
          onBack={() => setView("home")}
        />
      )}

      {view === "home" && (
        <>
          <Header
            onRegister={() => setView("register")}
            onCatalogue={() => setView("catalogue")}
            onCart={() => setView("cart")}
            cartCount={cartCount}
          />
          <Hero onRegister={() => setView("register")} />
          <HowItWorks />
          <CataloguePreview onBrowse={() => setView("catalogue")} />
          <RegisterCTA onRegister={() => setView("register")} />
          <Footer
            onAdmin={() => setView(adminPassword ? "admin" : "admin-login")}
          />
        </>
      )}
    </div>
  );
}
